def confirmar_evolucion_git(mensaje: str) -> None:
    """Realiza un commit automático si el repo es Git."""
    if DRY_RUN: return
    try:
        # Verificar si es un repo git
        subprocess.run(["git", "rev-parse", "--is-inside-work-tree"], capture_output=True, check=True)
        subprocess.run(["git", "add", "."], check=True)
        subprocess.run(["git", "commit", "-m", mensaje], check=True)
        print(f"{Color.VERDE}[GIT]{Color.RESET} Evolución confirmada con commit: {mensaje}")
    except Exception:
        # Si no es un repo git o falla, ignorar silenciosamente
        pass

